import { test, expect } from '@playwright/test';

test.describe('Coupon Code Validation Error Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/coupon-validation');
  });

  test('should display error message when invalid coupon code is entered', async ({ page }) => {
    // Locate and fill coupon input using getByLabel
    const couponInput = page.getByLabel('Coupon Code');
    await couponInput.fill('INVALIDCODE123');

    // Locate and click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /apply coupon/i });
    await submitButton.click();

    // Wait for error message to appear
    await page.waitForTimeout(500);

    // Verify error message is visible and contains expected text
    const errorMessage = page.getByText(/invalid coupon code/i);
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('The coupon code you entered is invalid.');

    // Verify error message has appropriate styling (e.g, red color)
    const errorBox = page.locator('[data-testid="error-message"]');
    await expect(errorBox).toHaveCSS('color', 'rgb(255, 0, 0)');

    // Verify coupon input still has the invalid value
    await expect(couponInput).toHaveValue('INVALIDCODE123');
  });

  test('should clear error message when valid coupon code is entered', async ({ page }) => {
    // Enter invalid coupon code first
    const couponInput = page.getByLabel('Coupon Code');
    await couponInput.fill('INVALIDCODE123');
    const submitButton = page.getByRole('button', { name: /apply coupon/i });
    await submitButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid coupon code/i);
    await expect(errorMessage).toBeVisible();

    // Clear the input field
    await couponInput.clear();

    // Enter valid coupon code
    await couponInput.fill('VALIDCODE123');

    // Click submit button again
    await submitButton.click();

    // Wait for success state
    await page.waitForTimeout(500);

    // Verify error message is no longer visible
    const errorBox = page.locator('[data-testid="error-message"]');
    await expect(errorBox).not.toBeVisible();

    // Verify success message is displayed
    const successMessage = page.getByText(/coupon applied successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify coupon input now contains the valid code
    await expect(couponInput).toHaveValue('VALIDCODE123');
  });
});
